body:
{
  "pains": [
    {
      "id": "pain:pajama-time",
      "statement": "I see my last patient at five and then spend my evening finishing notes and clearing a bottomless inbox.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Notes left open at the end of clinic get finished at home after hours.",
        "operational": "Documentation runs past the clinic day, notes get written hours after the visit and miss detail, and the inbox piles on top.",
        "personal": "Evenings at home go to the EHR, and burnout follows: 57% of family physicians say they are burned out."
      },
      "workflow": "Ambulatory clinic day in Epic: visit, then the progress note typed or dictated in Epic or Dragon between patients, the rest finished after clinic from home alongside the In Basket messages, refills and forms.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A clinic day ends with unsigned notes and a full In Basket, and the physician takes them home.",
          "cites": ["src:6"]
        },
        {
          "event": "The health system puts burnout on the leadership agenda and starts an ambient listening program.",
          "cites": ["src:2", "src:12"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "tending to a seemingly bottomless inbox of messages, correspondence, and forms.",
              "cites": ["src:6"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "my notes are done within 5 min of the last patient getting checked out.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Evenings and family time, and the burnout that comes with charting at home.",
          "fears": "That the note will be finished from memory hours later and miss what actually happened in the room.",
          "dream_outcome": "The note is done when the last patient walks out and the evening belongs to them."
        },
        "champion": {
          "says": [
            {
              "situation": "to_their_boss",
              "verbatim": "We set out to solve one of our biggest challenges in healthcare, which is around clinician burnout.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Clinician turnover and recruiting costs while burnout stays high.",
          "fears": "Losing physicians the system cannot replace.",
          "dream_outcome": "Clinicians stop charting at home and stay."
        }
      },
      "relief": {
        "line": "Notes done at checkout. The last note is signed minutes after the last patient leaves.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "my notes are done within 5 min of the last patient getting checked out.",
            "cites": ["src:1"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Medicine feels human again. The visit is a conversation, not typing, and it becomes the expectation of the job.",
        "says": [
          {
            "role": "champion",
            "verbatim": "We can give you back some of not only your time, but also some of the humanity of the doctor-patient visit.",
            "cites": ["src:12"]
          }
        ],
        "gap": null
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:clinician",
      "cites": ["src:6", "src:1", "src:2", "src:12"],
      "priority": 1,
      "felt_evidence": {
        "kind": "paying",
        "what": "Health systems pay for ambient scribes to cut after-hours charting: at UCSF about 70% of physicians use one, and Mass General Brigham bought one to address clinician burnout.",
        "cites": ["src:12", "src:2"]
      }
    },
    {
      "id": "pain:proofread-every-note",
      "statement": "The AI note is close, but I still have to proofread every line because a wrong dose or an invented detail lands on my license.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "AI drafts contain wrong medication doses, extra HPI detail, or a thin assessment and plan.",
        "operational": "Every note needs a full review before signing, and the assessment and plan often get rewritten, which eats the time saved.",
        "personal": "Errors signed under their name are a liability, and reviewing someone else's draft is its own tiring work."
      },
      "workflow": "After the visit, the physician opens the ambient draft in the Epic note or the vendor app, checks HPI and medications, rewrites the assessment and plan, then signs.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A physician catches a wrong dose or an invented detail in a draft note.",
          "cites": ["src:1"]
        },
        {
          "event": "Leadership sets a human-in-the-loop review rule for every AI-drafted note.",
          "cites": ["src:12"]
        }
      ],
      "who_feels": ["end_user", "blocker"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I notice there are still a lot of mistakes with medication doses, names, etc.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "assessment not as detailed as I like, so I spend some time there.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "any time saved with DAX would be erased by time that I would have to spend reviewing and editing the AI generated notes.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Minutes per note spent editing, and the mental load of checking a draft they did not write.",
          "fears": "Signing a note with a wrong dose or an invented fact under their name.",
          "dream_outcome": "A draft they can trust, with every line traceable to what was said."
        },
        "blocker": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "end up with a lot of mistakes in their notes and thats a liability IMO.",
              "cites": ["src:1"]
            },
            {
              "situation": "to_their_boss",
              "verbatim": "the human-in-the-loop idea sounds better on paper than it is in reality.",
              "cites": ["src:12"]
            }
          ],
          "costs_them": "Patient safety and malpractice exposure if reviews are skipped.",
          "fears": "Clinicians rubber-stamp AI drafts and errors enter the legal record.",
          "dream_outcome": "Reviews are fast because errors are rare and easy to check against the source."
        }
      },
      "relief": {
        "line": "Edit, not write. A few minutes of edits instead of typing the whole note.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "But if it took 3-5 minutes to edit, it probably would have taken 10-15 minute to type out.",
            "cites": ["src:1"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "The AI note beats my own. It is a truer record of the visit than what they used to write.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "The AI notes are concise and amazingly accurate.",
            "cites": ["src:5"]
          }
        ],
        "gap": null
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:clinician",
      "cites": ["src:1", "src:5", "src:12"],
      "priority": 2,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Family physicians on r/FamilyMedicine in 2025 describe dose and name errors in AI notes and say everyone must proofread everything every time.",
        "cites": ["src:1"]
      }
    },
    {
      "id": "pain:roi-unprovable",
      "statement": "The scribes cost more every year and the time savings look tiny, so I cannot show the CFO this pays for itself.",
      "element": "b2b:table_stakes:acceptable_price",
      "shape": {
        "surface": "Per-clinician license costs rise while measured time savings are modest.",
        "operational": "Pilots win on clinician feeling but have no standard ROI framework, so renewals and expansion stall in budget review.",
        "personal": "The CMIO who championed it has to defend a growing line item with soft burnout numbers."
      },
      "workflow": "Annual budget and renewal cycle: CMIO and IT leadership present ambient pilot results (EHR time logs, surveys) to the CFO to fund expansion past the pilot cohort.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A contract renewal or enterprise expansion goes to the CFO.",
          "cites": ["src:2", "src:11"]
        },
        {
          "event": "Published studies show smaller time savings than vendors pitched.",
          "cites": ["src:2", "src:12"]
        }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "Is that enough to justify these increasing costs of ambient dictation software?",
              "cites": ["src:2"]
            },
            {
              "situation": "to_their_boss",
              "verbatim": "Quantifying these outcomes financially remains elusive.",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "Rising per-seat spend without a hard return to show.",
          "fears": "Paying for an enterprise license that does not move productivity or revenue.",
          "dream_outcome": "A clear financial case: throughput, coding and retention that pay for the licenses."
        },
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "It looks like the time savings are really quite modest, if not negligible.",
              "cites": ["src:2"]
            },
            {
              "situation": "to_their_boss",
              "verbatim": "But consistently across studies people are reporting being less burned out, with less cognitive load in the process.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Credibility when the numbers they promised do not show up.",
          "fears": "Losing the program at renewal after clinicians come to depend on it.",
          "dream_outcome": "Numbers that justify the spend on their own."
        }
      },
      "relief": {
        "line": "It pays for itself. Throughput and time savings cover the license.",
        "says": [
          {
            "role": "champion",
            "verbatim": "probably pay for itself in pure throughput and time savings",
            "cites": ["src:12"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Nobody asks about ROI anymore. The scribe is an expectation of working here, part of how they recruit and keep doctors.",
        "says": [
          {
            "role": "champion",
            "verbatim": "almost become an expectation of practice now",
            "cites": ["src:12"]
          }
        ],
        "gap": null
      },
      "segments": ["seg:system"],
      "feature_ref": "feat:rcm",
      "feature_note": "Revenue cycle documentation is the feature that gives a hard-dollar case; clinician time savings alone do not.",
      "cites": ["src:2", "src:11", "src:12"],
      "priority": 3,
      "felt_evidence": {
        "kind": "complaining",
        "what": "In December 2025, CMIOs at Boston Children's and Mass General Brigham said publicly that time savings are modest and questioned whether reduced burnout justifies rising costs.",
        "cites": ["src:2"]
      }
    },
    {
      "id": "pain:undercoded-visits",
      "statement": "We have been billing below the work we actually do because the note never captured it.",
      "element": "b2b:functional:improved_top_line",
      "shape": {
        "surface": "Notes written fast or hours later leave out decision-making the visit really involved.",
        "operational": "Visits get coded at lower E/M levels than the work supports, and revenue is left on the table without anyone seeing it.",
        "personal": null,
        "personal_note": "No source has a physician or coder describing a personal cost; the evidence is claims-level and from analysts."
      },
      "workflow": "Physician signs a brief note in Epic, picks an E/M level, and coding or professional billing codes from what the note supports.",
      "type": "latent",
      "confidence": "medium",
      "triggers": [
        {
          "event": "After an ambient rollout, claims data shows the E/M mix shifting upward and leaders ask whether they were undercoding before.",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_looking",
              "verbatim": "it probably suggests that, historically, providers have actually been under-coding their visits",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Professional fee revenue the work earned but the note did not support.",
          "fears": "That capturing it now looks like upcoding to payers.",
          "dream_outcome": "Every visit billed at the level the documented work supports, no more, no less."
        },
        "end_user": {
          "says": [
            {
              "situation": "when_comparing",
              "verbatim": "those written or dictated hours after the visit, often missed essential information",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Work done in the room that never shows up in the record.",
          "fears": "Being asked to document more just to bill correctly.",
          "dream_outcome": "The note captures the full visit without extra typing."
        }
      },
      "relief": {
        "line": "The note matches the visit. What happened in the room is in the record.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "these AI-enabled scribing tools are allowing clinical documentation to be captured more thoroughly and accurately",
            "cites": ["src:3"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Revenue that holds up. Billing reflects the work and survives audit.",
        "says": [],
        "gap": "Searched trade press, KLAS coverage and Reddit; no buyer has described a lasting revenue change from ambient documentation in their own words, only vendor case studies we could not open."
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:rcm",
      "revealed_by": "feat:rcm",
      "cites": ["src:3", "src:5"],
      "priority": 4,
      "felt_evidence": null
    },
    {
      "id": "pain:nurse-behind-workstation",
      "statement": "My nurses spend their shift behind the workstation charting instead of in front of their patients.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Flowsheets and notes pull nurses to the computer through the shift and past its end.",
        "operational": "Documentation competes with bedside time, and charting left over runs past shift end.",
        "personal": "Less time with patients, and worry that a new tool just adds work to an already full day."
      },
      "workflow": "Inpatient med-surg shift in Epic: assessments and care entered into flowsheets and narrative notes at the workstation, end-of-shift documentation before handoff.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Nursing leadership sees nurses spending more time at workstations than at the bedside and pilots ambient documentation.",
          "cites": ["src:4"]
        },
        {
          "event": "The health system extends ambient AI from physicians to nursing after a physician rollout.",
          "cites": ["src:4", "src:10"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "champion": {
          "says": [
            {
              "situation": "to_their_boss",
              "verbatim": "our nurses were spending a lot of time behind the workstation instead of really in front of their patients",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Bedside time, patient experience and nurse retention.",
          "fears": "A tool that nurses reject because narrating care feels unnatural.",
          "dream_outcome": "Documentation happens in the background while nurses stay with patients."
        },
        "end_user": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "Is it going to add to my day? Is it going to be more work for me?",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Time with patients, and charting that spills past the shift.",
          "fears": "Another tool that adds steps, or that puts wrong data in the chart.",
          "dream_outcome": "Charting is done by the end of the shift without extra work."
        }
      },
      "relief": {
        "line": "Charting moves to the background. Documentation stops pulling nurses away from the bedside.",
        "says": [
          {
            "role": "champion",
            "verbatim": "moves the documentation burden away and moves documentation to the background",
            "cites": ["src:10"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Nurses talk to patients again. Communication with patients improves for good.",
        "says": [
          {
            "role": "champion",
            "verbatim": "This really has helped with the communication with nurses and their patients, for sure",
            "cites": ["src:4"]
          }
        ],
        "gap": null
      },
      "segments": ["seg:nursing"],
      "feature_ref": "feat:nursing",
      "cites": ["src:4", "src:10"],
      "priority": 5,
      "felt_evidence": {
        "kind": "paying",
        "what": "Mount Sinai Medical Center expanded ambient AI to nurses in 2026, and six early-adopter organisations are running Abridge's nursing flowsheet tool per KLAS.",
        "cites": ["src:4", "src:10"]
      }
    },
    {
      "id": "pain:codes-not-supported",
      "statement": "The AI writes a long note, but if it does not support the code we billed, CDI queries the doctor and payers come after us.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "AI-drafted notes do not line up with the selected billing codes.",
        "operational": "CDI and revenue cycle teams flag mismatches, queries go back to clinicians, and payers watch for coding intensity jumps after scribe rollouts.",
        "personal": "Coders and clinicians redo work by hand, and leaders carry False Claims Act and audit exposure."
      },
      "workflow": "After the note is signed in Epic, CDI specialists and coders review documentation against selected E/M and diagnosis codes, send queries to the physician, and payers run claims analytics on E/M distribution.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "CDI query volume spikes after an ambient scribe goes live.",
          "cites": ["src:7"]
        },
        {
          "event": "Payer analytics flag a step-change in high-level E/M codes at a facility.",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["blocker", "economic_buyer"],
      "by_role": {
        "blocker": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Clinicians and administrative staff are left to correct errors or fill in gaps manually",
              "cites": ["src:7"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "The goal of using this generative AI tool is never to upcode, never to overcharge.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Rework on queries and denials, and the efficiency gain lost downstream.",
          "fears": "Being accused of upcoding because the AI documented more.",
          "dream_outcome": "Notes that support the code from the start, so queries and denials drop."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "What we found, I think pretty clearly, was a massive step-change growth at facilities.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Denials, downcoding and audit risk on revenue the scribe was meant to protect.",
          "fears": "Payers targeting the health system for coding intensity.",
          "dream_outcome": "Higher-acuity coding that is defensible line by line."
        }
      },
      "relief": {
        "line": "Codes the note can defend. Documentation supports the billed level, so CDI stops chasing doctors.",
        "says": [],
        "gap": "Searched CDI and coding trade coverage; the only description of this relief came from a competing vendor's CMO, not a coder or revenue cycle buyer."
      },
      "euphoria": {
        "line": "Audit-proof revenue. Coding intensity rises and holds up when payers look.",
        "says": [],
        "gap": "No coder, CDI lead or revenue cycle buyer in the sources describes a lasting post-rollout state; coverage is analyst and vendor commentary."
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:rcm",
      "cites": ["src:7", "src:3"],
      "priority": 6,
      "felt_evidence": {
        "kind": "complaining",
        "what": "In March 2026 a payer analytics firm publicly described a massive step-change in coding at facilities using AI scribes, and health systems saw CDI queries surge after coding-naive scribes.",
        "cites": ["src:3", "src:7"]
      }
    },
    {
      "id": "pain:licenses-unused",
      "statement": "We rolled it out and half the doctors barely use it or use it in clunky ways.",
      "element": "b2b:functional:scalability",
      "shape": {
        "surface": "Clinicians with access do not turn it on, or keep their old documentation habits.",
        "operational": "Adoption ranges widely by specialty and setting, so paid seats sit idle and the program cannot scale past early adopters.",
        "personal": "Champions own a rollout that looks like it is failing."
      },
      "workflow": "Post-go-live: informatics tracks activation per clinician in Epic and vendor dashboards, runs training and specialty template tuning to raise use.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Usage reports after go-live show low activation in some specialties.",
          "cites": ["src:11", "src:13"]
        }
      ],
      "who_feels": ["champion", "end_user"],
      "by_role": {
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Others switch it on, but stick to their old documentation habits, under-utilizing the AI or using it in clunky ways.",
              "cites": ["src:13"]
            }
          ],
          "costs_them": "Paid seats that do not deliver, and a weak case for expansion.",
          "fears": "The program stalls at early adopters.",
          "dream_outcome": "Most clinicians use it every visit without being chased."
        },
        "end_user": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "It takes me the same or more time, but decreases my cognitive burden.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Setup and editing time that does not pay back for their visit style.",
          "fears": "Changing a documentation habit that already works for them.",
          "dream_outcome": "A tool that fits how they already document."
        }
      },
      "relief": {
        "line": "Everyone uses it. Most clinicians use it and like it.",
        "says": [
          {
            "role": "champion",
            "verbatim": "At UCSF, roughly 70% of physicians now use one, and 90% of those physicians say they love it.",
            "cites": ["src:12"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "It is how they practise now. The scribe is an expectation of the job.",
        "says": [
          {
            "role": "champion",
            "verbatim": "almost become an expectation of practice now",
            "cites": ["src:12"]
          }
        ],
        "gap": null
      },
      "segments": ["seg:system", "seg:specialty"],
      "feature_ref": "feat:clinician",
      "cites": ["src:11", "src:13", "src:12", "src:1"],
      "priority": 7,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A surgeon wrote in October 2025 that clinicians often use their clinic's ambient scribe wrong or barely at all; PHTI reports adoption from 20% to 80% by specialty.",
        "cites": ["src:13", "src:11"]
      }
    },
    {
      "id": "pain:recording-consent",
      "statement": "We are recording patient visits with AI and now we are getting sued over whether patients really consented.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Patients say they were not told visits would be recorded and sent to a third party.",
        "operational": "Class actions under state privacy and wiretap laws force systems to rework consent scripts and documentation of consent.",
        "personal": null,
        "personal_note": "The sources quote complaints and a spokesperson, not a CMIO or privacy officer describing the personal cost."
      },
      "workflow": "Start of each visit: clinician asks for verbal consent to record, the ambient app records, audio goes to the vendor, the draft note lands in Epic.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A class action names a health system for recording visits without meaningful consent.",
          "cites": ["src:9"]
        }
      ],
      "who_feels": ["blocker", "economic_buyer"],
      "by_role": {
        "blocker": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "without obtaining meaningful, informed consent from patients prior to recording",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "Legal exposure and patient trust.",
          "fears": "Being the next named defendant.",
          "dream_outcome": "Consent captured and provable for every recorded visit."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "We take patient privacy seriously and are committed to protecting the security of our patients' information.",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "Litigation cost and reputational damage on a tool rolled out to every clinic.",
          "fears": "Pausing the program while legal reviews consent.",
          "dream_outcome": "Keep ambient documentation running with no consent risk."
        }
      },
      "relief": {
        "line": "Consent on record. Every recorded visit shows the patient agreed.",
        "says": [],
        "gap": "Searched legal and trade coverage of the Sharp and Sutter suits; no buyer has described a fixed consent state yet."
